/* IASELO · écrans « Qualité & sécurité » (événements indésirables, RMM, mode dégradé), « Agenda des consultations »,
   « Honoraires & paiements » et « Logistique du bloc » (brancardage, stérilisation, planning des équipes).
   Socle commun et autres outils : dist/marche.js. Règles : dist/marche-regles.js. Serveur : worker/marche.mjs. */
(function(root){
'use strict';
const OUTILS=root.IaseloOutils=root.IaseloOutils||{};
const R=()=>root.IaseloMarche;
const opts=(obj,sel)=>Object.entries(obj).map(([k,v])=>`<option value="${k}" ${String(k)===String(sel)?'selected':''}>${String(v).replace(/</g,'&lt;')}</option>`).join('');
const plusJours=(iso,n)=>{const d=new Date(iso+'T12:00');d.setDate(d.getDate()+n);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')};
const JOURS=['dim.','lun.','mar.','mer.','jeu.','ven.','sam.'];

/* =====================================================================
   6 + 4. Qualité & sécurité
   ===================================================================== */
OUTILS.qualite={
 async html(K){
  const e=K.etat.qualite??={};const j=await K.api('evenements'),M=R(),ouverts=j.ei.filter(x=>x.status!=='clos');
  const o=K.onglets('qualite',[['declarer','Déclarer'],['ei',j.gestion?'Événements à traiter':'Mes déclarations',j.gestion?ouverts.length:0],...(j.medecin||j.gestion?[['rmm','RMM']]:[]),['secours','Mode dégradé']]);
  if(e.onglet==='declarer')return o+`<form class="mk-card" data-mk-action="declarer" data-mk-ok="Déclaration enregistrée : merci. La qualité vous répondra."><p class="mk-sub">Déclarer sert à apprendre, pas à sanctionner. Vous pouvez demander la confidentialité : votre nom n’est alors visible que de la cellule qualité.</p>
   <div class="mk-grid"><label>Catégorie<select name="categorie" required><option value="">Choisir…</option>${opts(M.CATEGORIES_EI)}</select></label><label>Date<input type="date" name="date" value="${K.jourISO()}" required></label><label>Gravité<select name="gravite">${opts(M.GRAVITE_EI,2)}</select></label><label>Conséquence pour le patient<select name="consequence">${opts({aucune:'Aucune',temporaire:'Atteinte temporaire',prolongation:'Prolongation du séjour',deficit:'Déficit fonctionnel permanent probable',pronostic:'Mise en jeu du pronostic vital',deces:'Décès'},'aucune')}</select></label><label>Lieu<input name="lieu" maxlength="200" placeholder="Ex. bloc, salle 2"></label><label>Patient concerné (facultatif)${K.choixPatient('','stay','Aucun / non lié')}</label></div>
   <label>Ce qui s’est passé<textarea name="description" rows="4" required minlength="10" maxlength="6000"></textarea></label><label>Mesures prises immédiatement<textarea name="mesuresImmediates" rows="2" maxlength="2000"></textarea></label><label class="mk-check"><input type="checkbox" name="anonyme" value="1"> Déclaration confidentielle</label>
   <p class="mk-sub">Décès, mise en jeu du pronostic vital ou déficit permanent probable : événement indésirable grave associé aux soins (EIGS), à déclarer sans délai à l’ARS ; la qualité vous accompagne.</p><button class="primary" type="submit">Déclarer</button></form>`;
  if(e.onglet==='ei')return o+(j.ei.length?`<ul class="mk-list">${j.ei.map(x=>ei(K,x,j.gestion)).join('')}</ul>`:'<p class="notice">Aucun événement.</p>');
  if(e.onglet==='rmm'){const rmm=j.rmm;return o+`<form class="mk-card mk-row" data-mk-action="rmm-creer" data-mk-ok="Séance créée"><label>Date<input type="date" name="date" required></label><label>Intitulé<input name="titre" required placeholder="RMM anesthésie – bloc"></label><label>Spécialité<input name="specialite"></label><button class="primary" type="submit">Programmer une RMM</button></form>
   ${rmm.map(s=>`<section class="mk-card"><h3>${K.esc(s.data.titre)} · ${K.esc(K.fr(s.data.date))} ${K.chip(s.status==='tenue'?'Tenue':'Prévue',s.status==='tenue'?'ok':'warn')}</h3>
    ${s.data.cas.length?`<ol class="mk-mini">${s.data.cas.map(c=>`<li>${K.esc(c.resume)}${c.evitable?' · évitable : '+K.esc(c.evitable):''}${c.causes.length?' · causes : '+K.esc(c.causes.map(x=>M.CAUSES_ALARM[x]).join(', ')):''}</li>`).join('')}</ol>`:'<p class="mk-sub">Aucun cas inscrit.</p>'}
    ${s.status==='tenue'?`<p><b>Présents</b> : ${K.esc(s.data.presents.join(', '))}</p><p><b>Conclusion</b> : ${K.esc(s.data.conclusion)}</p>${s.data.actions.length?`<ul class="mk-mini">${s.data.actions.map(a=>`<li>${K.esc(a.libelle)} · ${K.esc(a.responsable)} · ${K.esc(K.fr(a.echeance))}</li>`).join('')}</ul>`:''}`:`
    <form data-mk-action="rmm-cas" data-mk-ok="Cas ajouté"><input type="hidden" name="id" value="${K.esc(s.id)}"><h4>Ajouter un cas (anonymisé)</h4><label>Résumé<textarea name="resume" rows="2" required></textarea></label><div class="mk-grid"><label>Événement lié<select name="ei"><option value="">—</option>${j.ei.map(x=>`<option value="${K.esc(x.id)}">${K.esc(M.CATEGORIES_EI[x.data.categorie])} · ${K.esc(K.fr(x.data.date))}</option>`).join('')}</select></label><label>Évitable<select name="evitable"><option value="">—</option><option value="oui">Oui</option><option value="peut-etre">Peut-être</option><option value="non">Non</option></select></label></div><div class="mk-checks">${Object.entries(M.CAUSES_ALARM).map(([k,v])=>`<label class="mk-check"><input type="checkbox" name="causes" value="${k}"> ${K.esc(v)}</label>`).join('')}</div><label>Analyse<textarea name="analyse" rows="2"></textarea></label><button class="secondary" type="submit">Ajouter le cas</button></form>
    <form data-mk-action="rmm-conclure" data-mk-ok="RMM conclue"><input type="hidden" name="id" value="${K.esc(s.id)}"><h4>Conclure la séance</h4><label>Présents (un par ligne)<textarea name="presents" rows="3" required></textarea></label><label>Conclusion<textarea name="conclusion" rows="2"></textarea></label><div class="mk-grid"><label>Action d’amélioration<input name="aLibelle"></label><label>Responsable<input name="aResponsable"></label><label>Échéance<input type="date" name="aEcheance"></label></div><button class="primary" type="submit">Clore la séance</button></form>`}</section>`).join('')}`}
  return o+await secours(K);
 },
 brancher(host,K){
  K.brancher(host,'evenements',(f,o)=>{const a=f.dataset.mkAction;
   if(a==='declarer')return {...o,anonyme:!!o.anonyme,gravite:Number(o.gravite)};
   if(a==='rmm-cas')return {...o,causes:[].concat(o.causes||[])};
   if(a==='rmm-conclure')return {id:o.id,presents:o.presents,conclusion:o.conclusion,actions:o.aLibelle?[{libelle:o.aLibelle,responsable:o.aResponsable,echeance:o.aEcheance}]:[]};
   if(a==='analyse')return {...o,causes:[].concat(o.causes||[])};
   if(['debut','fin','ressaisie'].includes(a))return o;
   return o});
  brancherSecours(host,K);
 }
};
function ei(K,x,gestion){const M=R(),d=x.data;const ton={declare:'warn',analyse:'warn',actions:'warn',clos:'ok'}[x.status];
 return `<li class="mk-ei"><div><b>${K.esc(M.CATEGORIES_EI[d.categorie]||d.categorie)}</b> · ${K.esc(K.fr(d.date))} · gravité ${K.esc(M.GRAVITE_EI[d.gravite]||d.gravite)} ${K.chip(M.STATUTS_EI[x.status],ton)}${x.eigs?' '+K.chip('EIGS','crit'):''}
 <small>${K.esc(d.description)}</small><small>Déclaré par ${K.esc(x.par)} le ${K.esc(K.fr(x.at))}${x.stay?' · patient : '+K.esc(K.nomPatient(K.parId(x.stay))||'hors de vos équipes'):''}${d.lieu?' · '+K.esc(d.lieu):''}</small>
 ${x.echeances.length?`<ul class="mk-mini">${x.echeances.map(e=>`<li>${e.fait?'✓':'○'} ${K.esc(e.label)}${e.fait?'':` · avant le ${K.esc(K.fr(e.echeance))}`}${gestion&&!e.fait?` <button type="button" class="secondary mk-small" data-mk-btn="declaration-externe" data-mk-data='${K.esc(JSON.stringify({id:x.id,cle:e.cle}))}'>Fait</button>`:''}</li>`).join('')}</ul>`:''}
 ${d.causes?.length||d.analyse?`<small>Analyse : ${K.esc((d.causes||[]).map(c=>M.CAUSES_ALARM[c]).join(', '))} ${K.esc(d.analyse||'')}</small>`:''}
 ${(d.actions||[]).length?`<ul class="mk-mini">${d.actions.map(a=>`<li>${a.fait?'✓':'○'} ${K.esc(a.libelle)} · ${K.esc(a.responsable||'')} ${a.echeance?'· '+K.esc(K.fr(a.echeance)):''}${gestion&&!a.fait?` <button type="button" class="secondary mk-small" data-mk-btn="action-faite" data-mk-data='${K.esc(JSON.stringify({id:x.id,actionId:a.id}))}'>Faite</button>`:''}</li>`).join('')}</ul>`:''}</div>
 ${gestion?`<div class="mk-actions">${({declare:['analyse','clos'],analyse:['actions','clos'],actions:['clos'],clos:['analyse']}[x.status]||[]).map(v=>`<button type="button" class="secondary" data-mk-btn="statut" data-mk-data='${K.esc(JSON.stringify({id:x.id,vers:v}))}'>${K.esc({analyse:'Analyser',actions:'Actions en cours',clos:'Clore'}[v]||v)}</button>`).join('')}
  <details><summary>Analyse et actions</summary><form data-mk-action="analyse" data-mk-ok="Analyse enregistrée"><input type="hidden" name="id" value="${K.esc(x.id)}"><div class="mk-checks">${Object.entries(M.CAUSES_ALARM).map(([k,v])=>`<label class="mk-check"><input type="checkbox" name="causes" value="${k}" ${(d.causes||[]).includes(k)?'checked':''}> ${K.esc(v)}</label>`).join('')}</div><label>Analyse (méthode ALARM)<textarea name="analyse" rows="2">${K.esc(d.analyse||'')}</textarea></label><label>Évitable<select name="evitable"><option value="">—</option>${opts({oui:'Oui','peut-etre':'Peut-être',non:'Non'},d.evitable)}</select></label><button class="secondary" type="submit">Enregistrer l’analyse</button></form>
  <form data-mk-action="action" data-mk-ok="Action ajoutée"><input type="hidden" name="id" value="${K.esc(x.id)}"><div class="mk-grid"><label>Action corrective<input name="libelle" required></label><label>Responsable<input name="responsable"></label><label>Échéance<input type="date" name="echeance"></label></div><button class="secondary" type="submit">Ajouter</button></form></details></div>`:''}</li>`}

/* ---------- Mode dégradé ---------- */
async function secours(K){
 const j=await K.api('secours'),ouvert=j.episodes.find(e=>e.status==='en-cours'),aRessaisir=j.episodes.filter(e=>e.status==='a-ressaisir');
 const pts=K.patients().filter(s=>s.stage!=='Sortie');
 return `<section class="mk-card"><h3>Classeur de secours ${ouvert?K.chip('Mode dégradé en cours depuis '+K.heure(ouvert.data.debut),'crit'):''}</h3>
  <p class="mk-sub">À préparer chaque matin et à chaque changement d’équipe : une fiche par patient présent ou attendu (identité, allergies, intervention, ASA, voies aériennes, traitements, consignes, prescriptions en cours). Il sert si IASELO, le réseau ou l’électricité tombent.</p>
  <div class="mk-row"><button type="button" class="primary" data-s="imprimer">Imprimer le classeur (${pts.length} patient${pts.length>1?'s':''})</button><button type="button" class="secondary" data-s="vierges">Imprimer les feuilles vierges</button></div>
  <form class="mk-row" data-s="fichier"><label>Phrase de secours<input type="password" name="secret" minlength="12" required autocomplete="new-password" placeholder="12 caractères au moins"></label><button type="submit" class="secondary">Télécharger le fichier chiffré pour le poste de secours</button></form>
  <p class="mk-sub">Le fichier chiffré (AES-256) s’ouvre sans réseau dans n’importe quel navigateur, avec la phrase de secours. Gardez-le sur le poste de secours du service, jamais sur une clé personnelle. Chaque préparation est tracée.</p></section>
 <section class="mk-card"><h3>Épisode de mode dégradé</h3>${ouvert?`<p>Ouvert par ${K.esc(ouvert.par)} à ${K.esc(K.fr(ouvert.data.debut))} · motif : ${K.esc(ouvert.data.motif)}</p><form data-mk-action="fin" data-mk-module="secours" data-mk-ok="Fin du mode dégradé : pensez à ressaisir"><input type="hidden" name="id" value="${K.esc(ouvert.id)}"><label>Bilan<textarea name="bilan" rows="2"></textarea></label><button class="primary" type="submit">Fin de la panne : passer à la ressaisie</button></form>`
  :`<form class="mk-row" data-mk-action="debut" data-mk-module="secours" data-mk-ok="Mode dégradé déclaré"><label>Motif<input name="motif" required placeholder="Panne réseau, coupure électrique…"></label><button class="secondary" type="submit">Déclarer le passage en mode dégradé</button></form>`}
  ${aRessaisir.map(e=>`<div class="mk-card"><h4>Ressaisie après la panne du ${K.esc(K.fr(e.data.debut))} ${K.chip('À ressaisir','warn')}</h4><p class="mk-sub">Ressaisir dans IASELO les feuilles papier remplies pendant la panne (constantes, administrations, transmissions), puis cocher chaque patient.</p><ul class="mk-mini">${e.data.resaisies.map(r=>`<li>✓ ${K.esc(K.nomPatient(K.parId(r.stay))||r.stay)} · ${K.esc(r.par)} · ${K.esc(K.fr(r.at))}</li>`).join('')}</ul>
   <form class="mk-row" data-mk-action="ressaisie" data-mk-module="secours" data-mk-ok="Ressaisie notée"><input type="hidden" name="id" value="${K.esc(e.id)}"><label>Patient ressaisi${K.choixPatient('')}</label><button class="secondary" type="submit">Noter</button></form><button type="button" class="secondary" data-mk-module="secours" data-mk-btn="clore" data-mk-data='${K.esc(JSON.stringify({id:e.id}))}'>Clore l’épisode</button></div>`).join('')}</section>`;
}
function brancherSecours(host,K){
 const M=R(),pts=()=>K.patients().filter(s=>s.stage!=='Sortie').map(M.ficheSecours);
 host.querySelector('[data-s=imprimer]')?.addEventListener('click',async()=>{const f=pts();await K.api('secours',{body:{action:'kit',patients:f.length,forme:'impression'}}).catch(()=>{});imprimer(classeurHtml(f,K),K)});
 host.querySelector('[data-s=vierges]')?.addEventListener('click',()=>imprimer(viergesHtml(),K));
 const f=host.querySelector('form[data-s=fichier]');if(f)f.onsubmit=async e=>{e.preventDefault();const secret=f.secret.value,err=M.erreurSecret(secret);if(err){K.erreur(f,Error(err));return}
  const fiches=pts();try{const html=await fichierChiffre(fiches,secret);await K.api('secours',{body:{action:'kit',patients:fiches.length,forme:'fichier-chiffre'}});const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([html],{type:'text/html'}));a.download='iaselo-secours-'+K.jourISO()+'.html';document.body.append(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},1000);f.reset();K.toast?.('Fichier de secours téléchargé ('+fiches.length+' patients)')}catch(x){K.erreur(f,x)}};
}
const ligneFiche=(l,v)=>v?`<tr><th>${l}</th><td>${String(v).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c])).replace(/\n/g,'<br>')}</td></tr>`:'';
function ficheHtml(f){return `<section class="fiche"><h2>${ligneFiche('','').length?'':''}${(f.nom+' '+f.prenom).replace(/</g,'&lt;')}</h2><p class="id">Né(e) le ${f.naissance?f.naissance.split('-').reverse().join('/'):'—'}${f.sexe?' · '+f.sexe:''}${f.ins?' · INS '+f.ins:''} · séjour ${f.id}</p><table>
 ${ligneFiche('Allergies',f.allergies)}${ligneFiche('Intervention',[f.intervention,f.cote&&f.cote!=='Sans objet'?f.cote:'',f.dateIntervention?f.dateIntervention.split('-').reverse().join('/'):''].filter(Boolean).join(' · '))}${ligneFiche('Étape',[f.etape,f.mode,f.specialite].filter(Boolean).join(' · '))}${ligneFiche('ASA',f.asa)}${ligneFiche('Voies aériennes',f.vas)}${ligneFiche('Technique prévue',f.technique)}${ligneFiche('Antibioprophylaxie',f.atb)}${ligneFiche('Transfusion',f.transfusion)}${ligneFiche('Traitements habituels',f.traitements)}${ligneFiche('Consignes',f.consignes)}${ligneFiche('Prescriptions en cours',f.prescriptions.join('\n'))}</table></section>`}
const STYLE_SECOURS='body{font:13px/1.4 system-ui,sans-serif;color:#111;margin:16px}h1{font-size:18px}h2{font-size:16px;margin:0 0 2px}.id{margin:0 0 8px;color:#333}.fiche{border:1px solid #999;padding:10px 12px;margin:0 0 12px;break-inside:avoid}table{border-collapse:collapse;width:100%}th{text-align:left;width:170px;vertical-align:top;padding:3px 8px 3px 0;color:#333}td{padding:3px 0}.grille td,.grille th{border:1px solid #999;height:22px;padding:2px 4px;font-size:11px}.page{break-after:page}@media print{.no-print{display:none}}';
function classeurHtml(fiches,K){const d=new Date().toLocaleString('fr-FR');return `<h1>Classeur de secours · ${d}</h1><p>${fiches.length} patient(s). Document confidentiel : à ranger dans le classeur du service, détruire à la prochaine édition.</p>${fiches.map(ficheHtml).join('')||'<p>Aucun patient.</p>'}`}
function viergesHtml(){const h=[];for(let i=0;i<24;i++)h.push(`<th>${String(7+Math.floor(i/2)).padStart(2,'0')}:${i%2?'30':'00'}</th>`);
 const grille=(titre,lignes)=>`<div class="page"><h1>${titre} · mode dégradé</h1><p>Patient : ______________________ Né(e) le : ____/____/______ Séjour : ________ Salle : ____ Date : ____/____/______</p><table class="grille"><tr><th></th>${h.join('')}</tr>${lignes.map(l=>`<tr><th>${l}</th>${'<td></td>'.repeat(24)}</tr>`).join('')}</table><p>Rédigé par : __________________ Signature : ________ · À ressaisir dans IASELO dès le retour du système.</p></div>`;
 return grille('Feuille d’anesthésie',['PAS / PAD','FC','SpO₂','EtCO₂','T°','FiO₂','Halogéné','Médicaments','Solutés','Événements'])+grille('Pancarte de surveillance',['PA','FC','T°','SpO₂','FR','Douleur (EN)','Diurèse','Pansement','Transmissions'])+
 `<div class="page"><h1>Traçabilité transfusionnelle · mode dégradé</h1><table class="grille"><tr><th>N° de poche</th><th>Type</th><th>Groupe</th><th>Contrôle ultime (identité, concordance, carte)</th><th>Début</th><th>Fin</th><th>Surveillance</th><th>Signature</th></tr>${'<tr>'+'<td></td>'.repeat(8)+'</tr>'.repeat(10)}</table></div>`}
function imprimer(corps,K){const w=window.open('','_blank');if(!w){K.toast?.('Autorisez les fenêtres pour imprimer.');return}w.document.write(`<!doctype html><html lang="fr"><head><meta charset="utf-8"><title>IASELO · secours</title><style>${STYLE_SECOURS}</style></head><body>${corps}<script>setTimeout(()=>print(),300)<\/script></body></html>`);w.document.close()}
// Fichier autonome : données chiffrées (PBKDF2 310 000 itérations, AES-GCM 256) + page de déchiffrement sans réseau.
async function fichierChiffre(fiches,secret){
 const enc=new TextEncoder(),sel=crypto.getRandomValues(new Uint8Array(16)),iv=crypto.getRandomValues(new Uint8Array(12));
 const cle=await crypto.subtle.deriveKey({name:'PBKDF2',salt:sel,iterations:310000,hash:'SHA-256'},await crypto.subtle.importKey('raw',enc.encode(secret),'PBKDF2',false,['deriveKey']),{name:'AES-GCM',length:256},false,['encrypt']);
 const donnees=new Uint8Array(await crypto.subtle.encrypt({name:'AES-GCM',iv},cle,enc.encode(JSON.stringify({creeLe:new Date().toISOString(),fiches}))));
 const b64=u=>btoa(String.fromCharCode(...u));const b64long=u=>{let s='';for(let i=0;i<u.length;i+=32768)s+=String.fromCharCode(...u.subarray(i,i+32768));return btoa(s)};
 return `<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>IASELO · classeur de secours</title><style>${STYLE_SECOURS}form{margin:24px 0}input{font-size:16px;padding:6px}button{font-size:16px;padding:6px 14px}</style></head><body>
<h1>IASELO · classeur de secours</h1><p>Préparé le ${new Date().toLocaleString('fr-FR')} · ${fiches.length} patient(s). Saisissez la phrase de secours du service.</p>
<form id="f" class="no-print"><input type="password" id="s" autocomplete="off" autofocus> <button>Ouvrir</button> <span id="e" role="alert"></span></form><div id="c"></div>
<script>const D={sel:"${b64(sel)}",iv:"${b64(iv)}",donnees:"${b64long(donnees)}"};const u=s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0));const esc=s=>String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const L=(l,v)=>v?'<tr><th>'+l+'</th><td>'+esc(v).replace(/\\n/g,'<br>')+'</td></tr>':'';
document.getElementById('f').onsubmit=async e=>{e.preventDefault();try{const k=await crypto.subtle.deriveKey({name:'PBKDF2',salt:u(D.sel),iterations:310000,hash:'SHA-256'},await crypto.subtle.importKey('raw',new TextEncoder().encode(document.getElementById('s').value),'PBKDF2',false,['deriveKey']),{name:'AES-GCM',length:256},false,['decrypt']);
const x=JSON.parse(new TextDecoder().decode(await crypto.subtle.decrypt({name:'AES-GCM',iv:u(D.iv)},k,u(D.donnees))));document.getElementById('f').remove();
document.getElementById('c').innerHTML='<p class="no-print"><button onclick="print()">Imprimer</button></p>'+x.fiches.map(f=>'<section class="fiche"><h2>'+esc(f.nom+' '+f.prenom)+'</h2><p class="id">Né(e) le '+esc((f.naissance||'').split('-').reverse().join('/'))+' · séjour '+esc(f.id)+'</p><table>'+L('Allergies',f.allergies)+L('Intervention',[f.intervention,f.dateIntervention].filter(Boolean).join(' · '))+L('Étape',f.etape)+L('ASA',f.asa)+L('Voies aériennes',f.vas)+L('Technique prévue',f.technique)+L('Antibioprophylaxie',f.atb)+L('Transfusion',f.transfusion)+L('Traitements habituels',f.traitements)+L('Consignes',f.consignes)+L('Prescriptions en cours',(f.prescriptions||[]).join('\\n'))+'</table></section>').join('')}
catch{document.getElementById('e').textContent='Phrase incorrecte.'}}<\/script></body></html>`;
}

/* =====================================================================
   7. Agenda des consultations d'anesthésie
   ===================================================================== */
OUTILS.agenda={
 async html(K){
  const e=K.etat.agenda??={};if(!e.du)e.du=K.jourISO();const au=plusJours(e.du,6);
  const j=await K.api('agenda',{q:'du='+e.du+'&au='+au}),M=R(),sec=K.peut(['secretariat']),anesth=K.job()==='anesthesiste';
  const libres=M.libres(j.plages.filter(p=>p.statut==='ouverte'),j.rdv);
  const jours=Array.from({length:7},(_,i)=>plusJours(e.du,i));
  const statut={reserve:['Réservé','warn'],confirme:['Confirmé','ok'],honore:['Honoré','ok'],absent:['Absent','crit'],annule:['Annulé','']};
  return `<div class="mk-row"><button type="button" class="secondary" data-a="prec">← Semaine précédente</button><b>Semaine du ${K.esc(K.fr(e.du))}</b><button type="button" class="secondary" data-a="suiv">Semaine suivante →</button><button type="button" class="secondary" data-a="auj">Aujourd’hui</button></div>
  <div class="mk-agenda">${jours.map(d=>{const pl=j.plages.filter(p=>p.date===d);return `<div class="mk-jour"><h4>${JOURS[new Date(d+'T12:00').getDay()]} ${K.esc(d.slice(8))}/${K.esc(d.slice(5,7))}</h4>${pl.map(p=>`<div class="mk-plage ${p.statut==='fermee'?'fermee':''}"><b>${K.esc(p.debut)}–${K.esc(p.fin)}</b> ${K.esc(p.medecinNom)}<small>${K.esc(p.mode==='teleconsultation'?'Téléconsultation':p.lieu)}</small>
   ${M.creneaux(p).map(c=>{const r=j.rdv.find(x=>x.plage===p.id&&x.heure===c.heure&&x.statut!=='annule');return r?`<div class="mk-rdv"><span>${K.esc(c.heure)} · <b>${K.esc(r.patient)}</b></span>${K.chip(statut[r.statut]?.[0]||r.statut,statut[r.statut]?.[1]||'')}${r.par==='patient'?K.chip('en ligne',''):''}${r.alerte?`<small class="mk-warn">${K.esc(r.alerte)}</small>`:''}${r.stay&&['reserve','confirme'].includes(r.statut)?`<span class="mk-mini-actions">${['confirme','honore','absent','annule'].filter(s=>s!==r.statut).map(s=>`<button type="button" class="mk-small secondary" data-mk-btn="rdv-statut" data-mk-data='${K.esc(JSON.stringify({id:r.id,statut:s}))}'>${K.esc(statut[s][0])}</button>`).join('')}</span>`:''}</div>`:`<div class="mk-libre">${K.esc(c.heure)} · libre</div>`}).join('')}
   ${p.statut==='ouverte'&&(sec||anesth)?`<button type="button" class="mk-small secondary" data-mk-btn="fermer-plage" data-mk-data='${K.esc(JSON.stringify({id:p.id}))}' data-mk-confirm="Fermer cette plage ?">Fermer la plage</button>`:''}</div>`).join('')||'<p class="mk-sub">—</p>'}</div>`}).join('')}</div>
  <div class="mk-cols">
  <form class="mk-card" data-mk-action="rdv" data-mk-ok="Rendez-vous réservé"><h3>Donner un rendez-vous</h3><label>Patient${K.choixPatient(K.ctx.current()?.id||'')}</label><label>Créneau<select name="creneau" required>${libres.slice(0,200).map(c=>`<option value="${K.esc(c.plage+'|'+c.heure)}">${K.esc(K.fr(c.date))} ${K.esc(c.heure)} · ${K.esc(c.medecinNom)}${c.mode==='teleconsultation'?' (visio)':''}</option>`).join('')||'<option value="">Aucun créneau libre cette semaine</option>'}</select></label><label>Motif<input name="motif" maxlength="200" placeholder="Consultation pré-anesthésique"></label><button class="primary" type="submit">Réserver</button></form>
  <form class="mk-card" data-mk-action="lien" data-mk-ok="Lien envoyé au patient"><h3>Laisser le patient choisir</h3><p class="mk-sub">Le patient reçoit par SMS et e-mail un lien personnel (sa date de naissance lui est demandée) et choisit parmi les créneaux libres jusqu’à 2 jours avant l’intervention.</p><label>Patient${K.choixPatient(K.ctx.current()?.id||'')}</label><button class="secondary" type="submit">Envoyer le lien de prise de rendez-vous</button><div class="mk-lien" hidden></div></form>
  ${sec||anesth?`<form class="mk-card" data-mk-action="plage" data-mk-ok="Plage ouverte"><h3>Ouvrir une plage de consultation</h3><div class="mk-grid">${sec||K.admin()?`<label>Anesthésiste<select name="medecin" required>${j.medecins.map(m=>`<option value="${K.esc(m.id)}">${K.esc(m.nom)}</option>`).join('')}</select></label>`:''}<label>Date<input type="date" name="date" value="${K.esc(e.du)}" required></label><label>Début<input type="time" name="debut" value="09:00" required></label><label>Fin<input type="time" name="fin" value="12:00" required></label><label>Durée<select name="duree">${[15,20,30,45].map(x=>`<option ${x===20?'selected':''}>${x}</option>`).join('')}</select></label><label>Lieu<input name="lieu" placeholder="Cabinet d’anesthésie"></label><label>Mode<select name="mode"><option value="presentiel">Présentiel</option><option value="teleconsultation">Téléconsultation</option></select></label></div><button class="secondary" type="submit">Ouvrir la plage</button></form>`:''}</div>
  <p class="mk-sub">Doctolib reste possible pour la prise de rendez-vous : le connecteur est prêt en simulation et passera en réel avec l’accès fourni par Doctolib à la clinique.</p>`;
 },
 brancher(host,K){const e=K.etat.agenda;
  host.querySelector('[data-a=prec]').onclick=()=>{e.du=plusJours(e.du,-7);K.dessiner()};host.querySelector('[data-a=suiv]').onclick=()=>{e.du=plusJours(e.du,7);K.dessiner()};host.querySelector('[data-a=auj]').onclick=()=>{e.du=K.jourISO();K.dessiner()};
  K.brancher(host,'agenda',(f,o)=>{if(f.dataset.mkAction==='rdv'){const [plage,heure]=String(o.creneau||'').split('|');return {stay:o.stay,plage,heure,motif:o.motif}}return o},(j,f)=>{
   if(f.dataset?.mkAction==='lien'){const d=f.querySelector('.mk-lien');d.hidden=false;d.innerHTML=j.canaux?.length?'Envoyé par '+K.esc(j.canaux.join(' et ')):'<b>Aucune coordonnée vérifiée</b> : remettez ce lien au patient : <a href="'+K.esc(j.lien)+'" target="_blank" rel="noopener">'+K.esc(j.lien)+'</a>';return}
   if(j.alerte)K.toast?.(j.alerte);else K.toast?.(f.dataset?.mkOk||'Enregistré');K.dessiner()});
 }
};

/* =====================================================================
   9. Honoraires et paiements
   ===================================================================== */
OUTILS.honoraires={
 async html(K){
  const e=K.etat.honoraires??={};const stay=K.sejourCourant('honoraires'),M=R(),med=K.peut(['anesthesiste','chirurgien']),guichet=K.peut(['secretariat','facturation']);
  const tete=`<div class="mk-row"><label>Patient${K.choixPatient(stay).replace('<select','<select data-mk-choix="honoraires"')}</label></div>`;if(!stay)return tete;
  const j=await K.api('honoraires',{q:'stay='+encodeURIComponent(stay)}),els=j.elements,c=j.connecteurs;
  const devis=els.filter(x=>x.kind==='devis'),fses=els.filter(x=>x.kind==='fse'),pays=els.filter(x=>x.kind==='paiement');
  const sd={brouillon:'',envoye:'warn',signe:'ok',refuse:'crit',annule:''},sp={'a-payer':'warn',lien:'warn',paye:'ok',rembourse:'',annule:'',echec:'crit'};
  return tete+`<p class="mk-sub">${K.chip('SESAM-Vitale : '+c.sesam.mode,c.sesam.mode==='production'?'ok':'warn')} ${K.chip('Paiement en ligne : '+c.paiement.mode,c.paiement.mode==='production'?'ok':'warn')}</p>
  ${devis.map(d=>`<section class="mk-card"><h3>Devis de ${K.esc(d.data.praticien)} ${K.chip(M.STATUTS_DEVIS[d.status],sd[d.status])}${d.data.devisObligatoire?' '+K.chip('Information écrite obligatoire (≥ 70 €)',''):''}</h3>
   <table class="mk-table"><thead><tr><th>Acte</th><th>Base de remboursement</th><th>Honoraires</th><th>Dépassement</th></tr></thead><tbody>${d.data.lignes.map(l=>`<tr><td>${K.esc(l.code)} ${K.esc(l.libelle)}</td><td>${M.euros(l.base)}</td><td>${M.euros(l.demande)}</td><td>${M.euros(l.depassement)}</td></tr>`).join('')}<tr><th>Total</th><td>${M.euros(d.data.base)}</td><td><b>${M.euros(d.data.total)}</b></td><td><b>${M.euros(d.data.depassement)}</b></td></tr></tbody></table>
   ${d.data.pav?`<p class="mk-sub">Participation forfaitaire de ${M.euros(d.data.pav)} à la charge du patient (acte ≥ ${M.SEUIL_PAV} €), sauf exonération.</p>`:''}${d.data.alertes.map(a=>`<p class="notice warn">${K.esc(a)}</p>`).join('')}
   ${d.data.signature?`<p>${d.data.signature.accepte?'Accepté':'Refusé'} par le patient (${K.esc(d.data.signature.nom)}) le ${K.esc(K.fr(d.data.signature.at))}</p>`:''}
   <div class="mk-row">${med&&d.status==='brouillon'?`<button type="button" class="primary" data-mk-btn="envoyer-devis" data-mk-data='${K.esc(JSON.stringify({stay,id:d.id}))}' data-mk-apres="1">Envoyer au patient pour signature</button>`:''}${med&&(d.status==='signe'||!d.data.devisObligatoire)&&!fses.some(f=>f.data.devis===d.id&&f.status==='transmise')?`<button type="button" class="secondary" data-mk-btn="fse" data-mk-data='${K.esc(JSON.stringify({stay,id:d.id}))}' data-mk-ok="Feuille de soins transmise">Établir la feuille de soins</button>`:''}<button type="button" class="secondary" data-imprimer-devis="${K.esc(d.id)}">Imprimer</button></div><div class="mk-lien" hidden></div></section>`).join('')}
  ${fses.length?`<section class="mk-card"><h3>Feuilles de soins</h3><ul class="mk-mini">${fses.map(f=>`<li>${K.esc(K.fr(f.at))} · ${M.euros(f.data.total)} ${K.chip(f.status==='transmise'?(f.data.envoi?.simulation?'Simulation':'Transmise'):'Échec',f.status==='transmise'?'ok':'crit')} ${K.esc(f.data.envoi?.reference||f.data.envoi?.detail||'')}</li>`).join('')}</ul></section>`:''}
  ${med?`<form class="mk-card" data-mk-action="devis" data-mk-ok="Devis enregistré"><h3>Nouveau devis d’honoraires</h3><input type="hidden" name="stay" value="${K.esc(stay)}"><div class="mk-grid"><label>Secteur<select name="secteur"><option value="2">Secteur 2</option><option value="1">Secteur 1</option></select></label><label class="mk-check"><input type="checkbox" name="optam" value="1"> Adhérent OPTAM / OPTAM-CO</label><label>Date d’intervention<input type="date" name="dateIntervention"></label></div>
   ${[0,1,2].map(i=>`<div class="mk-grid"><label>Code CCAM<input name="code" placeholder="Ex. ZZLP025"></label><label>Libellé<input name="libelle"></label><label>Base (€)<input name="base" inputmode="decimal"></label><label>Honoraires demandés (€)<input name="demande" inputmode="decimal"></label></div>`).join('')}<button class="primary" type="submit">Calculer et enregistrer</button></form>`:''}
  <section class="mk-card"><h3>Paiements du patient</h3>${pays.length?`<ul class="mk-mini">${pays.map(p=>`<li>${K.esc(p.data.libelle)} · ${M.euros(p.data.montant)} · réf. ${K.esc(p.data.reference)} ${K.chip(M.STATUTS_PAIEMENT[p.status],sp[p.status])}${p.data.paiement?.simulation?' '+K.chip('simulation',''):''}${guichet&&!['paye','annule'].includes(p.status)?` <button type="button" class="mk-small secondary" data-mk-btn="paiement-statut" data-mk-data='${K.esc(JSON.stringify({stay,id:p.id,statut:'paye',moyen:'Guichet'}))}'>Payé au guichet</button>`:''}</li>`).join('')}</ul>`:'<p class="mk-sub">Aucune demande de paiement.</p>'}
   ${guichet?`<form data-mk-action="paiement" data-mk-ok="Lien de paiement envoyé"><input type="hidden" name="stay" value="${K.esc(stay)}"><div class="mk-grid"><label>Objet<select name="objet"><option value="chambre">Chambre particulière</option><option value="depassement">Complément d’honoraires</option><option value="autre">Autre prestation</option></select></label><label>Montant (€)<input name="montant" inputmode="decimal" required></label></div><button class="secondary" type="submit">Envoyer le lien de paiement</button><div class="mk-lien" hidden></div></form><p class="mk-sub">Le SMS ne mentionne ni l’objet ni aucune information médicale : seulement le montant et une référence.</p>`:''}</section>`;
 },
 brancher(host,K){const M=R();
  K.brancher(host,'honoraires',(f,o)=>{if(f.dataset.mkAction==='devis'){const a=k=>[].concat(o[k]||[]);return {stay:o.stay,secteur:o.secteur,optam:!!o.optam,dateIntervention:o.dateIntervention,lignes:a('code').map((c,i)=>({code:c,libelle:a('libelle')[i],base:a('base')[i],demande:a('demande')[i]})).filter(l=>l.code||l.base)}}return o},(j,f)=>{
   const lien=(f.closest?.('section,form')||f).querySelector('.mk-lien');if(lien&&(j.lien||j.canaux)){lien.hidden=false;lien.innerHTML=j.canaux?.length?'Envoyé par '+K.esc(j.canaux.join(' et ')):'<b>Aucune coordonnée vérifiée</b> : remettez ce lien au patient : <a href="'+K.esc(j.lien)+'" target="_blank" rel="noopener">'+K.esc(j.lien)+'</a>';setTimeout(()=>K.dessiner(),j.canaux?.length?1200:15000);return}
   K.toast?.(f.dataset?.mkOk||'Enregistré');K.dessiner()});
  host.querySelectorAll('[data-imprimer-devis]').forEach(b=>b.onclick=async()=>{const j=await K.api('honoraires',{q:'stay='+encodeURIComponent(K.etat.honoraires.stay)});const d=j.elements.find(x=>x.id===b.dataset.imprimerDevis);const s=K.parId(d.stay);
   const w=window.open('','_blank');if(!w)return;w.document.write(`<!doctype html><html lang="fr"><head><meta charset="utf-8"><title>Devis</title><style>body{font:13px system-ui;margin:24px}table{border-collapse:collapse;width:100%}td,th{border:1px solid #999;padding:4px 6px;text-align:left}</style></head><body><h1>Information préalable sur les honoraires</h1><p>Praticien : ${K.esc(d.data.praticien)} · secteur ${K.esc(d.data.secteur)}${d.data.optam?' (OPTAM)':''}</p><p>Patient : ${K.esc(K.nomPatient(s))} · né(e) le ${K.esc(K.naissance(s))}</p><table><tr><th>Acte</th><th>Base de remboursement</th><th>Honoraires</th><th>Dépassement</th></tr>${d.data.lignes.map(l=>`<tr><td>${K.esc(l.code)} ${K.esc(l.libelle)}</td><td>${M.euros(l.base)}</td><td>${M.euros(l.demande)}</td><td>${M.euros(l.depassement)}</td></tr>`).join('')}<tr><th>Total</th><td>${M.euros(d.data.base)}</td><td>${M.euros(d.data.total)}</td><td>${M.euros(d.data.depassement)}</td></tr></table><p>Le dépassement n’est pas remboursé par l’Assurance maladie ; il peut l’être en partie par votre complémentaire santé.</p><p>Date et signature du patient :</p><script>print()<\/script></body></html>`);w.document.close()});
 }
};

/* =====================================================================
   10. Logistique du bloc : brancardage, stérilisation, planning
   ===================================================================== */
OUTILS.logistique={
 async html(K){
  const e=K.etat.logistique??={},M=R(),bloc=K.peut(['infirmier','pharmacien','anesthesiste','chirurgien'])&&document.body.dataset.poste!=='etage';
  const o=K.onglets('logistique',[['brancardage','Brancardage'],...(bloc?[['sterilisation','Stérilisation']]:[]),['planning','Planning des équipes']]);
  if(e.onglet==='brancardage'){const j=await K.api('brancardage'),ordre=['demande','pris','parti','arrive','annule'];
   return o+`<form class="mk-card" data-mk-action="demande" data-mk-module="brancardage" data-mk-ok="Demande envoyée"><h3>Demander un transport</h3><div class="mk-grid"><label>Patient${K.choixPatient(K.ctx.current()?.id||'')}</label><label>Départ<input name="depart" required placeholder="Chambre 204"></label><label>Arrivée<input name="arrivee" required placeholder="Bloc, salle 2"></label><label>Priorité<select name="priorite">${opts(M.PRIORITES,'normal')}</select></label><label>Mode<select name="mode">${opts({brancard:'Brancard',lit:'Lit',fauteuil:'Fauteuil',pied:'À pied accompagné'})}</select></label><label>Heure souhaitée<input type="time" name="heure"></label><label>Isolement<input name="isolement" placeholder="Ex. contact"></label><label class="mk-check"><input type="checkbox" name="oxygene" value="1"> Oxygène</label></div><button class="primary" type="submit">Envoyer</button></form>
    <div class="mk-kanban">${ordre.slice(0,4).map(s=>`<div><h4>${K.esc(M.ETATS_TRANSPORT[s])} <b class="mk-count">${j.demandes.filter(d=>d.etat===s).length}</b></h4>${j.demandes.filter(d=>d.etat===s).map(d=>`<div class="mk-carte ${d.priorite==='urgent'?'urgent':''}"><b>${K.esc(d.patient)}</b><span>${K.esc(d.depart)} → ${K.esc(d.arrivee)}</span><small>${K.esc(M.PRIORITES[d.priorite])} · ${K.esc(d.mode)}${d.oxygene?' · O₂':''}${d.isolement?' · isolement '+K.esc(d.isolement):''} · demandé ${K.esc(K.heure(d.at))}${d.brancardier?' · '+K.esc(d.brancardier):''}</small>${d.retard?K.chip('Retard '+d.retard+' min','crit'):''}<span class="mk-mini-actions">${(M.SUIVANT_TRANSPORT[s]||[]).map(v=>`<button type="button" class="mk-small secondary" data-mk-module="brancardage" data-mk-btn="etat" data-mk-data='${K.esc(JSON.stringify({id:d.id,vers:v}))}'>${K.esc({pris:'Prendre en charge',parti:'Parti',arrive:'Arrivé',annule:'Annuler',demande:'Remettre en attente'}[v])}</button>`).join('')}</span></div>`).join('')}</div>`).join('')}</div>`}
  if(e.onglet==='sterilisation'){const j=await K.api('sterilisation'),ecrit=K.peut(['infirmier','pharmacien']);const ton={sterile:'ok',perimee:'crit',quarantaine:'crit',sale:'warn',lavage:'warn',conditionnee:'warn',utilisee:'',reforme:''};
   return o+`<table class="mk-table"><thead><tr><th>Boîte</th><th>État</th><th>Dernier cycle</th><th>Péremption</th><th></th></tr></thead><tbody>${j.boites.map(b=>`<tr><td><b>${K.esc(b.nom)}</b> <small>${K.esc(b.code)}${b.specialite?' · '+K.esc(b.specialite):''}</small></td><td>${K.chip(b.etatCalcule.label,ton[b.etatCalcule.code])}</td><td>${b.cycle?K.esc(b.cycle.autoclave+' · '+b.cycle.numero+' · '+K.fr(b.cycle.date)):'—'}</td><td>${b.peremption?K.esc(K.fr(b.peremption)):'—'}</td><td>${ecrit?{sale:['lavage','Lavée'],utilisee:['lavage','Lavée'],lavage:['conditionnee','Conditionnée']}[b.etat]?.length?`<button type="button" class="mk-small secondary" data-mk-module="sterilisation" data-mk-btn="etat" data-mk-data='${K.esc(JSON.stringify({boite:b.id,etat:{sale:'lavage',utilisee:'lavage',lavage:'conditionnee'}[b.etat]}))}'>${{sale:'Lavée',utilisee:'Lavée',lavage:'Conditionnée'}[b.etat]}</button>`:'':''}${ecrit&&b.etatCalcule.utilisable?`<form class="mk-inline" data-mk-action="utiliser" data-mk-module="sterilisation" data-mk-ok="Boîte tracée au patient"><input type="hidden" name="boite" value="${K.esc(b.id)}">${K.choixPatient(K.ctx.current()?.id||'')}<label class="mk-check"><input type="checkbox" name="atnc" value="1"> Patient à risque ATNC</label><button class="mk-small primary" type="submit">Utiliser</button></form>`:''}</td></tr>`).join('')||'<tr><td colspan="5">Aucune boîte enregistrée.</td></tr>'}</tbody></table>
    ${ecrit?`<div class="mk-cols"><form class="mk-card" data-mk-action="cycle" data-mk-module="sterilisation"><h3>Libérer une charge d’autoclave</h3><div class="mk-checks">${j.boites.filter(b=>b.etat==='conditionnee').map(b=>`<label class="mk-check"><input type="checkbox" name="boites" value="${K.esc(b.id)}"> ${K.esc(b.nom)} (${K.esc(b.code)})</label>`).join('')||'<span class="mk-sub">Aucune boîte conditionnée.</span>'}</div><div class="mk-grid"><label>Autoclave<input name="autoclave" required></label><label>N° de cycle<input name="numero" required></label><label>Programme<input name="programme" value="134 °C 18 min"></label>${['bowieDick:Test de Bowie-Dick du jour','indicateur:Indicateur / intégrateur','enregistrement:Enregistrement des paramètres','siccite:Siccité de la charge'].map(x=>{const [k,l]=x.split(':');return `<label>${l}<select name="${k}"><option value="conforme">Conforme</option><option value="non-conforme">Non conforme</option></select></label>`}).join('')}</div><button class="primary" type="submit">Enregistrer et libérer</button></form>
    <form class="mk-card" data-mk-action="boite" data-mk-module="sterilisation" data-mk-ok="Boîte enregistrée"><h3>Nouvelle boîte</h3><div class="mk-grid"><label>Nom<input name="nom" required></label><label>Code (étiquette)<input name="code" required></label><label>Spécialité<input name="specialite"></label><label>Conditionnement<select name="conditionnement">${opts({conteneur:'Conteneur (6 mois)',double_sachet:'Double sachet (3 mois)',feuille:'Feuille (1 mois)'})}</select></label></div><label>Composition<textarea name="composition" rows="2"></textarea></label><button class="secondary" type="submit">Enregistrer</button></form></div>
    <h3>Derniers cycles</h3><ul class="mk-mini">${j.cycles.map(c=>`<li>${K.esc(K.fr(c.at))} · ${K.esc(c.autoclave)} n° ${K.esc(c.numero)} · ${c.boites.length} boîte(s) ${K.chip(c.statut==='libere'?'Libéré':'Non libéré',c.statut==='libere'?'ok':'crit')} ${c.defauts.length?K.esc(c.defauts.join(' ')):'par '+K.esc(c.liberePar)}</li>`).join('')}</ul>`:''}`}
  if(!e.jour)e.jour=K.jourISO();const j=await K.api('planning',{q:'du='+e.jour+'&au='+e.jour}),manques=M.couverture(e.jour,j.salles,j.affectations),conf=M.chevauchements(j.affectations);
  return o+`<div class="mk-row"><label>Jour<input type="date" data-p="jour" value="${K.esc(e.jour)}"></label></div>${manques.length?`<div class="notice warn"><b>Couverture à compléter</b><ul class="mk-mini">${manques.map(m=>`<li>${K.esc(m)}</li>`).join('')}</ul></div>`:'<p class="notice">Couverture complète : chaque salle a son anesthésiste et son infirmier(ère), SSPI et nuit couvertes.</p>'}${conf.map(c=>`<p class="notice warn">${K.esc(c.motif)}</p>`).join('')}
  <table class="mk-table"><thead><tr><th>Fonction</th><th>Personne</th><th>Salle</th><th>Horaires</th><th></th></tr></thead><tbody>${j.affectations.sort((a,b)=>(a.salle||'~').localeCompare(b.salle||'~')||a.fonction.localeCompare(b.fonction)).map(a=>`<tr><td>${K.esc(M.FONCTIONS[a.fonction]||a.fonction)}</td><td>${K.esc(a.personne)}</td><td>${K.esc(j.salles.find(s=>s.id===a.salle)?.label||a.salle||'—')}</td><td>${K.esc(a.debut)}–${K.esc(a.fin)}</td><td>${j.peutModifier?`<button type="button" class="mk-small secondary" data-mk-module="planning" data-mk-btn="retirer" data-mk-data='${K.esc(JSON.stringify({id:a.id}))}'>Retirer</button>`:''}</td></tr>`).join('')||'<tr><td colspan="5">Aucune affectation.</td></tr>'}</tbody></table>
  ${j.peutModifier?`<form class="mk-card" data-mk-action="affecter" data-mk-module="planning" data-mk-ok="Affectation ajoutée"><h3>Affecter</h3><input type="hidden" name="date" value="${K.esc(e.jour)}"><div class="mk-grid"><label>Fonction<select name="fonction">${opts(M.FONCTIONS)}</select></label><label>Personne<input name="personne" required></label><label>Salle<select name="salle"><option value="">—</option>${j.salles.map(s=>`<option value="${K.esc(s.id)}">${K.esc(s.label)}</option>`).join('')}</select></label><label>Début<input type="time" name="debut" value="08:00"></label><label>Fin<input type="time" name="fin" value="18:00"></label></div><button class="primary" type="submit">Ajouter</button></form>`:'<p class="mk-sub">Planning tenu par les anesthésistes et la cadre de bloc.</p>'}`;
 },
 brancher(host,K){const e=K.etat.logistique;
  host.querySelector('[data-p=jour]')?.addEventListener('change',ev=>{e.jour=ev.target.value;K.dessiner()});
  K.brancher(host,'brancardage',(f,o)=>{const a=f.dataset.mkAction;
   if(a==='demande')return {...o,oxygene:!!o.oxygene,heureSouhaitee:o.heure?new Date(K.jourISO()+'T'+o.heure).toISOString():''};
   if(a==='cycle')return {...o,boites:[].concat(o.boites||[])};
   if(a==='utiliser')return {boite:o.boite,stay:o.stay,atnc:{cjd:!!o.atnc}};
   return o},(j,f)=>{if(j.defauts?.length)K.toast?.('Charge non libérée : '+j.defauts.join(' '));else if(j.quarantaine)K.toast?.('Patient à risque ATNC : boîte mise en quarantaine');else if(j.error)K.toast?.(j.error);else K.toast?.(f.dataset?.mkOk||'Enregistré');K.dessiner()});
 }
};
})(window);
